contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount <= address(this).balance);

        uint before = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        uint afterBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert(afterBal == before && cBalAfter == cBalBefore);
    }

    receive() external payable {}
}

